CREATE TABLE users (id VARCHAR(40) PRIMARY KEY, username VARCHAR(40) UNIQUE NOT NULL, password_hash VARCHAR(200) NOT NULL, role VARCHAR(10) NOT NULL, factor VARCHAR(10), secret TEXT, phone TEXT, last_otp BIGINT DEFAULT -1 NOT NULL, created BIGINT NOT NULL);
CREATE TABLE invites (code_hash VARCHAR(64) PRIMARY KEY, expires BIGINT NOT NULL, remaining INT NOT NULL, role VARCHAR(10) NOT NULL, created BIGINT NOT NULL);
CREATE TABLE sessions (token_hash VARCHAR(64) PRIMARY KEY, user_id VARCHAR(40) REFERENCES users(id), verified BOOLEAN NOT NULL, expires BIGINT NOT NULL);
CREATE TABLE recovery_codes (user_id VARCHAR(40) REFERENCES users(id), code_hash VARCHAR(64) PRIMARY KEY);
CREATE TABLE attempts (bucket VARCHAR(200) PRIMARY KEY, started BIGINT NOT NULL, count INT NOT NULL);
CREATE TABLE sandboxes (id VARCHAR(40) PRIMARY KEY, owner_id VARCHAR(40) REFERENCES users(id), name VARCHAR(80) NOT NULL, image_kind VARCHAR(20) NOT NULL, image_ref TEXT NOT NULL, state VARCHAR(30) NOT NULL, machine_id VARCHAR(80), app_name VARCHAR(80), volume_id VARCHAR(80), agent_hash VARCHAR(64), config TEXT NOT NULL, files TEXT NOT NULL, revision BIGINT NOT NULL DEFAULT 1, snapshot_id VARCHAR(40), tree TEXT NOT NULL DEFAULT '[]', idle_since BIGINT, lease_until BIGINT NOT NULL DEFAULT 0, next_action_at BIGINT, next_action VARCHAR(30), started_at BIGINT, ready_at BIGINT, session_id VARCHAR(40), error TEXT, bytes BIGINT NOT NULL DEFAULT 0, created BIGINT NOT NULL, updated BIGINT NOT NULL);
CREATE TABLE logs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sandbox_id VARCHAR(40) REFERENCES sandboxes(id), session_id VARCHAR(40), source VARCHAR(100) NOT NULL, event_key VARCHAR(100) UNIQUE, message TEXT NOT NULL, created BIGINT NOT NULL);
CREATE INDEX logs_sandbox ON logs(sandbox_id,id);
CREATE TABLE snapshots (id VARCHAR(40) PRIMARY KEY, sandbox_id VARCHAR(40) REFERENCES sandboxes(id), manifest TEXT NOT NULL, bytes BIGINT NOT NULL, created BIGINT NOT NULL);
CREATE TABLE chunks (sandbox_id VARCHAR(40) REFERENCES sandboxes(id), hash VARCHAR(64), bytes BIGINT NOT NULL, created BIGINT NOT NULL, PRIMARY KEY(sandbox_id,hash));
CREATE TABLE returns (id VARCHAR(40) PRIMARY KEY, sandbox_id VARCHAR(40) REFERENCES sandboxes(id), owner_id VARCHAR(40), left_at BIGINT NOT NULL, returned_at BIGINT);
CREATE INDEX returns_owner ON returns(owner_id);
CREATE TABLE measurements (id VARCHAR(40) PRIMARY KEY, sandbox_id VARCHAR(40) REFERENCES sandboxes(id), kind VARCHAR(40), seconds DOUBLE PRECISION, bytes BIGINT, created BIGINT NOT NULL);
CREATE TABLE decisions (id VARCHAR(40) PRIMARY KEY, sandbox_id VARCHAR(40) REFERENCES sandboxes(id), detail TEXT NOT NULL, created BIGINT NOT NULL);
CREATE TABLE prices (name VARCHAR(60) PRIMARY KEY, value DOUBLE PRECISION NOT NULL, updated BIGINT NOT NULL);
CREATE TABLE usage (id VARCHAR(40) PRIMARY KEY, sandbox_id VARCHAR(40) REFERENCES sandboxes(id), state VARCHAR(30), seconds DOUBLE PRECISION, estimated_usd DOUBLE PRECISION, created BIGINT NOT NULL);
CREATE TABLE settings (name VARCHAR(80) PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE preview_tokens (hash VARCHAR(64) PRIMARY KEY, sandbox_id VARCHAR(40) REFERENCES sandboxes(id), port INT NOT NULL, expires BIGINT NOT NULL);
